\left\{
\begin{array}{ll}
\displaystyle o\left(\tau^{-\lambda}\right), 
& \text{if } \mu\ne 1/2,\\
\displaystyle \mathcal{O}\left(\tau^{-2\lambda}\right),
& \text{if } \mu = 1/2,
