{\mathcal{S}}_\pm: 
  & a=a_{\pm}, & b=b_{\pm}, & r=r_{\pm}, & m=m_{\pm}, & s=\frac{1}{8}a_{\pm}, & i_0=-1,  & i_1=1,  & i_2=0,
\\
{\mathcal{S}}_1: 
 & a=\widetilde{a}, & b=\widetilde{b}, & r=\widetilde{r}, & m=\widetilde{m}, & s=0, & i_0=1,  & i_1=0,  & i_2=1.
